/**
 * Project inventory: renders the hotbar and the chest-like inventory overlay
 * from data/projects.json (generated by scripts/sync-github.mjs).
 *
 * Minecraft mapping of a project's state:
 *   stage      -> item name colour (rarity) + durability bar underneath
 *   stage.glint-> enchantment glint (live projects)
 *   tags       -> small badges on the slot
 *   stars      -> stack count in the bottom-right corner
 */
(function () {
  "use strict";

  var COLS = 9;
  var MIN_ROWS = 3;
  var LINK_COLOUR = "#55ff55";

  var data = { items: [], stages: {}, tags: {} };
  var filter = "all";
  var isOpen = false;

  var els = {};

  function cacheElements() {
    els.hotbar = document.getElementById("hotbar-container");
    els.overlay = document.getElementById("inventory-overlay");
    els.grid = document.getElementById("inventory-grid");
    els.tabs = document.getElementById("inventory-tabs");
    els.count = document.getElementById("inventory-count");
    els.tooltip = document.getElementById("tooltip");
    els.tooltipName = document.getElementById("tooltip-name");
    els.tooltipDesc = document.getElementById("tooltip-desc");
  }

  /* ----------------------------------------------------------- data helpers */

  function stageOf(item) {
    return (item.stage && data.stages[item.stage]) || null;
  }

  function colourOf(item) {
    var stage = stageOf(item);
    return stage ? stage.color : LINK_COLOUR;
  }

  function byId(id) {
    for (var i = 0; i < data.items.length; i++) {
      if (data.items[i].id === id) return data.items[i];
    }
    return null;
  }

  function visibleItems() {
    if (filter === "all") return data.items;
    return data.items.filter(function (item) {
      return item.stage === filter;
    });
  }

  function targetUrl(item) {
    return item.url || item.githubUrl || null;
  }

  /* -------------------------------------------------------------- rendering */

  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  /** Minecraft durability bars run green when full, red when nearly empty. */
  function durabilityBar(item) {
    var stage = stageOf(item);
    if (!stage || !stage.progress) return "";
    var hue = (stage.progress / 100) * 120;
    return (
      '<span class="slot-bar"><span class="slot-bar-fill" style="width:' +
      stage.progress +
      "%;background:hsl(" +
      hue +
      ',100%,45%)"></span></span>'
    );
  }

  function tagBadges(item) {
    if (!item.tags || !item.tags.length) return "";
    var badges = item.tags
      .map(function (id) {
        var tag = data.tags[id];
        if (!tag) return "";
        return (
          '<span class="slot-tag" style="background:' +
          tag.color +
          '" title="' +
          escapeHtml(tag.label) +
          '">' +
          escapeHtml(tag.badge || "*") +
          "</span>"
        );
      })
      .join("");
    return badges ? '<span class="slot-tags">' + badges + "</span>" : "";
  }

  function stackCount(item) {
    if (!item.stars) return "";
    return '<span class="slot-count">' + item.stars + "</span>";
  }

  function slotInner(item) {
    return (
      '<span class="slot-icon">' +
      escapeHtml(item.icon) +
      "</span>" +
      tagBadges(item) +
      stackCount(item) +
      durabilityBar(item)
    );
  }

  function isGlinting(item) {
    var stage = stageOf(item);
    return Boolean(stage && stage.glint);
  }

  function renderHotbar() {
    if (!els.hotbar) return;

    var bySlot = {};
    data.items.forEach(function (item) {
      if (item.slot >= 1 && item.slot <= COLS) bySlot[item.slot] = item;
    });

    var html = "";
    for (var slot = 1; slot <= COLS; slot++) {
      var item = bySlot[slot];
      if (!item) {
        html +=
          '<div class="hotbar-slot empty" data-slot="' +
          slot +
          '"><span class="slot-number">' +
          slot +
          "</span></div>";
        continue;
      }
      html +=
        '<div class="hotbar-slot' +
        (isGlinting(item) ? " enchanted" : "") +
        '" data-id="' +
        escapeHtml(item.id) +
        '"><span class="slot-number">' +
        slot +
        "</span>" +
        slotInner(item) +
        "</div>";
    }
    els.hotbar.innerHTML = html;
  }

  function renderTabs() {
    if (!els.tabs) return;

    var counts = {};
    data.items.forEach(function (item) {
      if (item.stage) counts[item.stage] = (counts[item.stage] || 0) + 1;
    });

    var tabs = [{ id: "all", label: "Tout", color: "#ffffff" }];
    Object.keys(data.stages)
      .filter(function (id) {
        return counts[id];
      })
      .sort(function (a, b) {
        return (data.stages[a].sort || 0) - (data.stages[b].sort || 0);
      })
      .forEach(function (id) {
        tabs.push({
          id: id,
          label: data.stages[id].label + " " + counts[id],
          color: data.stages[id].color,
        });
      });

    els.tabs.innerHTML = tabs
      .map(function (tab) {
        return (
          '<button type="button" class="inv-tab' +
          (filter === tab.id ? " active" : "") +
          '" data-filter="' +
          escapeHtml(tab.id) +
          '" style="--tab-color:' +
          tab.color +
          '">' +
          escapeHtml(tab.label) +
          "</button>"
        );
      })
      .join("");
  }

  function renderGrid() {
    if (!els.grid) return;

    var items = visibleItems();
    var rows = Math.max(MIN_ROWS, Math.ceil(items.length / COLS));
    var total = rows * COLS;
    var html = "";

    for (var i = 0; i < total; i++) {
      var item = items[i];
      if (!item) {
        html += '<div class="inv-slot empty"></div>';
        continue;
      }
      html +=
        '<div class="inv-slot' +
        (isGlinting(item) ? " enchanted" : "") +
        '" data-id="' +
        escapeHtml(item.id) +
        '">' +
        slotInner(item) +
        "</div>";
    }

    els.grid.innerHTML = html;
    if (els.count) {
      els.count.textContent =
        items.length + (items.length > 1 ? " items" : " item");
    }
  }

  /* --------------------------------------------------------------- tooltips */

  function formatDate(iso) {
    if (!iso) return null;
    var date = new Date(iso);
    if (isNaN(date)) return null;
    return date.toLocaleDateString("fr-FR", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  }

  function showTooltipFor(item) {
    if (!els.tooltip) return;

    els.tooltipName.textContent = item.name;
    els.tooltipName.style.color = colourOf(item);

    var lines = [];
    if (item.lore) lines.push({ text: item.lore, colour: "#aaaaaa" });

    var stage = stageOf(item);
    if (stage) lines.push({ text: stage.label, colour: stage.color });

    (item.tags || []).forEach(function (id) {
      var tag = data.tags[id];
      if (tag) lines.push({ text: tag.label, colour: tag.color });
    });

    var facts = [];
    if (item.language) facts.push(item.language);
    if (item.stars) facts.push(item.stars + " *");
    var pushed = formatDate(item.pushedAt);
    if (pushed) facts.push("maj " + pushed);
    if (facts.length) lines.push({ text: facts.join("  "), colour: "#7a7a7a" });

    if (item.repo) lines.push({ text: item.repo, colour: "#7a7a7a" });

    els.tooltipDesc.innerHTML = lines
      .map(function (line) {
        return (
          '<div style="color:' + line.colour + '">' + escapeHtml(line.text) + "</div>"
        );
      })
      .join("");

    els.tooltip.style.display = "block";
  }

  function showEmptySlotTooltip(slot) {
    if (!els.tooltip) return;
    els.tooltipName.textContent = "Slot vide";
    els.tooltipName.style.color = "#aaaaaa";
    els.tooltipDesc.innerHTML =
      '<div style="color:#aaaaaa">Assigne "slot": ' +
      slot +
      " dans data/projects.mapping.json</div>";
    els.tooltip.style.display = "block";
  }

  function hideTooltip() {
    if (els.tooltip) els.tooltip.style.display = "none";
  }

  /* ---------------------------------------------------------------- actions */

  function open(item) {
    var url = targetUrl(item);
    if (url) window.open(url, "_blank", "noopener");
  }

  function toggleInventory(force) {
    isOpen = typeof force === "boolean" ? force : !isOpen;
    if (els.overlay) els.overlay.classList.toggle("open", isOpen);
    document.body.classList.toggle("inventory-open", isOpen);
    hideTooltip();
    if (isOpen) {
      renderTabs();
      renderGrid();
    }
    if (window.history && window.history.replaceState) {
      window.history.replaceState(null, "", isOpen ? "#inventory" : "#");
    }
  }

  function setFilter(next) {
    filter = next;
    renderTabs();
    renderGrid();
  }

  /* ----------------------------------------------------------------- events */

  function slotFrom(event) {
    return event.target.closest ? event.target.closest("[data-id],[data-slot]") : null;
  }

  function bindSlotEvents(container) {
    if (!container) return;
    var hovered = null;

    container.addEventListener("click", function (event) {
      var el = slotFrom(event);
      if (!el) return;
      var id = el.getAttribute("data-id");
      if (!id) return;
      var item = byId(id);
      if (item) open(item);
    });

    // Delegation means moving onto a child re-fires mouseover, so only react
    // when the hovered slot actually changes.
    container.addEventListener("mouseover", function (event) {
      var el = slotFrom(event);
      if (el === hovered) return;
      hovered = el;

      if (!el) {
        hideTooltip();
        return;
      }
      var id = el.getAttribute("data-id");
      if (id) {
        var item = byId(id);
        if (item) showTooltipFor(item);
        return;
      }
      var slot = el.getAttribute("data-slot");
      if (slot) showEmptySlotTooltip(slot);
    });

    container.addEventListener("mouseleave", function () {
      hovered = null;
      hideTooltip();
    });
  }

  function bindEvents() {
    bindSlotEvents(els.hotbar);
    bindSlotEvents(els.grid);

    if (els.tabs) {
      els.tabs.addEventListener("click", function (event) {
        var button = event.target.closest("[data-filter]");
        if (button) setFilter(button.getAttribute("data-filter"));
      });
    }

    if (els.overlay) {
      els.overlay.addEventListener("click", function (event) {
        if (event.target === els.overlay) toggleInventory(false);
      });
    }

    var openButton = document.getElementById("inventory-open");
    if (openButton) {
      openButton.addEventListener("click", function () {
        toggleInventory();
      });
    }

    var closeButton = document.getElementById("inventory-close");
    if (closeButton) {
      closeButton.addEventListener("click", function () {
        toggleInventory(false);
      });
    }

    document.addEventListener("keydown", function (event) {
      var tag = event.target.tagName;
      if (tag === "INPUT" || tag === "TEXTAREA") return;

      if (event.key === "e" || event.key === "E") {
        event.preventDefault();
        toggleInventory();
        return;
      }
      if (event.key === "Escape" && isOpen) {
        toggleInventory(false);
        return;
      }
      if (isOpen) return;

      var slot = parseInt(event.key, 10);
      if (slot >= 1 && slot <= COLS) {
        var match = data.items.filter(function (item) {
          return item.slot === slot;
        })[0];
        if (match) open(match);
      }
    });
  }

  /* ------------------------------------------------------------------- boot */

  function init() {
    cacheElements();
    bindEvents();

    fetch("data/projects.json")
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        return res.json();
      })
      .then(function (payload) {
        data = payload;
        renderHotbar();
        renderTabs();
        if (window.location.hash === "#inventory") toggleInventory(true);
        else if (isOpen) renderGrid();
      })
      .catch(function (err) {
        console.warn(
          "Inventaire indisponible, lance `node scripts/sync-github.mjs`:",
          err.message
        );
      });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
